import * as THREE from 'three';
import { Hypercube } from '..';

export class SolarPanel {
	public hypercube: Hypercube;
	public meshGroup: THREE.Group;
	public pivot: THREE.Object3D;

	constructor(hypercube: Hypercube, meshGroup: THREE.Group) {
		this.hypercube = hypercube;
		this.meshGroup = meshGroup;

		this.initOffsetMesh();

		const pivotPos = new THREE.Vector3(0, 17, 15);

		const pivot = new THREE.Object3D();
		pivot.position.copy(pivotPos);
		this.pivot = pivot;

		this.meshGroup.position.sub(pivotPos);
		pivot.add(this.meshGroup);

		this.hypercube.sceneWrapper.scene.add(pivot);

		const pivotMarker = new THREE.Mesh(new THREE.SphereGeometry(0.001, 16, 16), new THREE.MeshBasicMaterial({ color: 0xff0000 }));
		pivotMarker.position.set(0, 0, 0);
		pivot.add(pivotMarker);

		const offset = 0.04;
		this.pivot.rotation.x = offset - Math.PI * 0.25 * 0.25 * 0.75;
	}
	public initOffsetMesh() {
		// this.meshGroup.position.x = -0.1;
		// this.meshGroup.position.z = 3.5;
	}
	public rotate(v: number) {
		const offset = 0.04;
		this.pivot.rotation.x = offset + (v - Math.PI * 0.25 * 0.25 * 0.75);
	}
	public set visible(v: boolean) {
		this.meshGroup.children.forEach((mesh) => {
			mesh.visible = v;
		});
	}
	public update() {
		// TODO
	}
}
