import { ThreeCore } from './ThreeCore';
import { AppCore } from './AppCore';
import { View } from './View';
import { CLICK_TYPE } from './Utils/const';

export class Solution {
	public view: View;
	public threeCore: ThreeCore;
	public appCore: AppCore;
	static Init(id: string) {
		const app = new Solution(id);
		return app;
	}
	constructor(id: string = 'main') {
		this.threeCore = new ThreeCore(id);
		this.view = new View(this);
		this.threeCore.initUI = () => {
			this.view.initPostUI();
		};

		const params = new URLSearchParams(window.location.search);
		const sc1 = params.get('sc');
		const needGlobe = sc1 === '1';

		const sc2 = params.get('performance');
		const isPerformanceMode = sc2 === 'true';

		this.appCore = new AppCore(this, isPerformanceMode, needGlobe);
		this.bindEvent();
		this.bindRenderer();
	}
	public bindEvent() {
		this.threeCore.onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => this.appCore.onMouseEventListener(e, type);
	}
	public bindRenderer() {
		this.threeCore.update = () => this.appCore.update();
	}
	public destroy() {
		this.view.destroy();
		this.appCore.destroy();
		this.threeCore.destroy();
	}
}
