import { NSolar } from 'lib/NJSCore';
import { AppCore } from '../';

import config from '../../Utils/config';

export class AppCommon {
	public appCore: AppCore;

	public solar: NSolar;

	private _showEnv = true;

	private _sampleCameraPositionIndex = 0;
	private _sampleCameraPosition = config.sampleCameraPosition;
	private _sampleCameraTargetPosition = config.sampleCameraTargetPosition;

	private _sampleHDRIIndex = -1;
	private _sampleHDRI = ['', 'bridgeSmall.hdr', 'controlroomSmall.hdr', 'outsiteSmall.hdr'];

	constructor(appCore: AppCore) {
		this.appCore = appCore;

		this.solar = new NSolar();
	}
	public get showEnv() {
		return this._showEnv;
	}
	public set showEnv(v: boolean) {
		this._showEnv = v;
		this.appCore.showStudioEnv(this._showEnv);
		if (this._showEnv) {
			this.appCore.sceneWrapper.substation.toggleVisibility(!this._showEnv);
		}
	}
	public get runningDroneDevices() {
		return this.appCore.sceneWrapper.hyperCube.runningDroneDevices;
	}
	public renderForce() {
		this.appCore.threeCore.renderForce();
	}
	public set runningDroneDevices(v: boolean) {
		this.renderForce();
		this.appCore.sceneWrapper.hyperCube.runningDroneDevices = v;
	}
	// ......................... controlling scene
	public hideAll() {
		this.appCore.sceneWrapper.hideAll();
	}
	public showHypercube() {
		this.appCore.sceneWrapper.hyperCube.show(true);
	}
	public toggleScene() {
		this.appCore.sceneWrapper.activateGlobe = !this.appCore.sceneWrapper.activateGlobe;
		this._sampleCameraPositionIndex = 0;
		if (this.appCore.sceneWrapper.activateGlobe) {
			this.appCore.sceneWrapper.showGlobe();
		} else {
			this.appCore.sceneWrapper.showStudioEnv();
		}
		this.appCore.threeCore.cameraStaring();
		this.renderForce();
	}
	public toggleStudioEnv() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.studioEnv) {
			this.appCore.sceneWrapper.studioEnv.show(!this.appCore.sceneWrapper.studioEnv.meshFloor.visible);
			this.appCore.sceneWrapper.hyperCube.show(!this.appCore.sceneWrapper.hyperCube.visible);
		}
		this.renderForce();
	}
	public toggleSubstation() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.substation) {
			this.appCore.sceneWrapper.hyperCube.show(true);
			this.appCore.sceneWrapper.substation.showSubstation();
		}
		this.renderForce();
	}
	public toggleSubstationDiorama() {
		this.appCore.sceneWrapper.hideAll();
		if (this.appCore.sceneWrapper.substation) {
			this.appCore.sceneWrapper.hyperCube.show(true);
			this.appCore.sceneWrapper.substation.showSubstationDiorama();
		}
		this.renderForce();
	}
	// ......................... end controlling scene
	public angleSolarPanel(v) {
		this.renderForce();
		this.appCore.sceneWrapper.hyperCube.angleSolarPanel = v;
	}
	public viewChangingForward() {
		this.viewChanging(this._sampleCameraPositionIndex);
		this._sampleCameraPositionIndex = (this._sampleCameraPositionIndex + 1) % this._sampleCameraPosition.length;
		this.renderForce();
	}
	public viewChangingBackward() {
		this._sampleCameraPositionIndex = (this._sampleCameraPositionIndex - 1 + this._sampleCameraPosition.length) % this._sampleCameraPosition.length;
		this.viewChanging(this._sampleCameraPositionIndex);
		this.renderForce();
	}
	public viewChanging(index: number) {
		const scale = 1;

		const vec = this._sampleCameraPosition[index];

		this.appCore.threeCore.cameraWrapper.duration = vec[3] !== undefined ? vec[3] : 1500;
		this.appCore.threeCore.cameraWrapper.moveCamera(vec[0] * scale, vec[1] * scale, vec[2] * scale);

		const vecT = this._sampleCameraTargetPosition[index];
		this.appCore.threeCore.cameraWrapper.moveTarget(vecT[0] * scale, vecT[1] * scale, vecT[2] * scale);
	}
	public changeFOV(value: number) {
		this.appCore.threeCore.cameraWrapper.changeFOV = value;
		this.renderForce();
	}
	public decompose() {
		this.appCore.sceneWrapper.hyperCube.decompose();
		this.renderForce();
	}
	public printCameraInfo() {
		this.appCore.threeCore.cameraWrapper.log();
	}
	public hdriChanging() {
		const val = this._sampleHDRI[this._sampleHDRIIndex++ % this._sampleHDRI.length];
		this.appCore.threeCore.initHDRI(val);
		this.renderForce();
	}

	public toggleHDRIBackground(toggle: boolean) {
		this.appCore.threeCore.toggleHDRIBackground(toggle);
		this.renderForce();
	}
	public toggleEffect(value: boolean | undefined = undefined) {
		this.appCore.threeCore.toggleEffect(value);
		this.renderForce();
	}
	public toggleShadow() {
		this.appCore.sceneWrapper.toggleShadow();
	}
	public getSubstationVisibility() {
		this.renderForce();
		if (this.appCore.sceneWrapper.substation) {
			return this.appCore.sceneWrapper.substation.visibility;
		}
		return false;
	}
	public getSunVec(Latitude: number, theDay: number, Hour) {
		// 30.23, Day: 100, Hour: 13
		const scale = 100;
		this.solar.Update(Latitude, theDay, Hour);

		this.appCore.threeCore.updateSolarVec(this.solar.VectorSun.x * scale, this.solar.VectorSun.y * scale, this.solar.VectorSun.z * scale);
		this.appCore.solution.view.metadataPosition.textContent = `Latitude: ${this.solar.latitude}, Day: ${this.solar.day}, Hour: ${this.solar.hour}`;
		this.renderForce();
	}
	public debuggerX(value: number) {
		// console.log("x: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.x = value;
		}
		this.renderForce();
	}
	public debuggerY(value: number) {
		// console.log("y: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.z = value;
		}
		this.renderForce();
	}
	public debuggerZ(value: number) {
		// console.log("z: ", value);
		if (this.appCore.activeCommand.selectedMesh) {
			this.appCore.activeCommand.selectedMesh.position.y = value;
		}
		this.renderForce();
	}
	public toggleAnimationRotatingA() {
		this.appCore.threeCore.toggleAnimationRotatingA();
		this.renderForce();
	}
	public toggleAnimationRotatingB() {
		this.appCore.threeCore.toggleAnimationRotatingB();
		this.renderForce();
	}
	// .... debug
	public roughness(value: number) {
		console.log('debuggerA:', value);

		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.roughness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.roughness = value;
			}
		}
		this.renderForce();
		// this.appCore.threeCore.togglePostProcessing();
	}

	public metalness(value: number) {
		console.log('metalness:', value);
		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.metalness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.metalness = value;
			}
		}
		this.renderForce();
	}
	public debuggerC(value: number) {
		console.log('debuggerC:', value);
		if (this.appCore.activeCommand.selectedMesh) {
			console.log(this.appCore.activeCommand.selectedMesh.material);

			if (Array.isArray(this.appCore.activeCommand.selectedMesh.material)) {
				for (let i = 0; i < this.appCore.activeCommand.selectedMesh.material.length; ++i) {
					const mat = this.appCore.activeCommand.selectedMesh.material[i];
					console.log(mat);
					mat.clearcoatRoughness = value;
				}
			} else {
				this.appCore.activeCommand.selectedMesh.material.clearcoatRoughness = value;
			}
		}
		this.renderForce();
	}
}
