import * as THREE from 'three';

import { ThreeCore } from '..';

// import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader';
import { RGBELoader } from 'three/examples/jsm/loaders/RGBELoader.js';
import { PMREMGenerator } from 'three';

import { getDirectionalLight, createStudioEnvironment } from '../../Utils';

export class LightWrapper {
	public threeCore: ThreeCore;

	public directionalLight = undefined;
	public envMap: THREE.Texture;

	// private skyMeshHDRI = undefined;
	private currentEnvironmentMap = undefined;

	constructor(threeCore: ThreeCore) {
		this.threeCore = threeCore;
		this.init();
	}
	async init() {
		await this.updateHDRI('bridgeSmall.hdr');

		this.directionalLight = getDirectionalLight(-500, 500, 500);
		this.threeCore.scene.add(this.directionalLight);

		// const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
		// ambientLight.castShadow = true;
		// this.threeCore.scene.add(ambientLight);

		// const HemiLight = new THREE.HemisphereLight(0xffffff, 0x444444, 1.5);
		// HemiLight.position.set(0, 10, 0);
		// this.threeCore.scene.add(HemiLight);

		// const pointLight = new THREE.PointLight(0xffffff, 100);
		// pointLight.position.x = 10;
		// pointLight.castShadow = true;
		// this.threeCore.scene.add(pointLight);

		this.threeCore.ready = true;
	}

	async updateHDRI(name: string = '', zUp = false) {
		const loader = new RGBELoader();
		const pmremGenerator = new PMREMGenerator(this.threeCore.renderer);
		pmremGenerator.compileEquirectangularShader();

		try {
			// if (this.skyMeshHDRI) {
			// 	this.threeCore.scene.remove(this.skyMeshHDRI);
			// 	this.skyMeshHDRI.geometry.dispose();
			// 	this.skyMeshHDRI.material.map?.dispose();
			// 	this.skyMeshHDRI.material.dispose();
			// 	this.skyMeshHDRI = undefined;
			// }

			if (this.currentEnvironmentMap) {
				this.currentEnvironmentMap.dispose();
				this.currentEnvironmentMap = undefined;
			}

			if (!name) {
				this.threeCore.scene.environment = undefined;
				this.threeCore.scene.background = undefined;
				return;
			}

			// const path = process.env.PUBLIC_URL + '/static/data/model/map/' + name;
			const path = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/' + name;
			const hdrEquirect = await loader.loadAsync(path);
			hdrEquirect.mapping = THREE.EquirectangularReflectionMapping;

			this.envMap = pmremGenerator.fromEquirectangular(hdrEquirect).texture;
			this.threeCore.scene.environment = this.envMap;
			this.threeCore.scene.background = this.envMap;
			this.currentEnvironmentMap = this.envMap;

			// const skyGeoHDRI = new THREE.SphereGeometry(2000, 60, 40);
			// const skyMatHDRI = new THREE.MeshBasicMaterial({
			// 	map: hdrEquirect,
			// 	side: THREE.BackSide,
			// });
			// const skyMeshHDRI = new THREE.Mesh(skyGeoHDRI, skyMatHDRI);
			// if (zUp) {
			// 	skyMeshHDRI.rotation.x = Math.PI / 2;
			// }
			// skyMeshHDRI.rotation.y = Math.PI;
			// // this.threeCore.scene.add(skyMeshHDRI);
			// this.skyMeshHDRI = skyMeshHDRI;

			hdrEquirect.dispose();
			pmremGenerator.dispose();
		} catch (error) {
			console.error('HDRI, fail to load:', error);
		}
	}
	public updateDirectionalLightVec(x: number, y: number, z: number) {
		if (!this.directionalLight) return;

		this.directionalLight.position.x = x;
		this.directionalLight.position.y = y;
		this.directionalLight.position.z = z;
	}
	public toggleHDRIBackground(value: boolean) {
		// console.log('hdir', value);
		if (value) {
			this.threeCore.scene.background = this.envMap;
			// this.skyMeshHDRI.visible = true;
		} else {
			this.threeCore.scene.background = undefined;
			// this.skyMeshHDRI.visible = false;
		}
	}
}
